def trapRainWater(heightMap: list[list[int]]) -> int:
    if not heightMap or not heightMap[0]: return 0
    R, C = len(heightMap), len(heightMap[0])
    import heapq
    visited = [[False] * C for _ in range(R)]
    pq = []
    for r in range(R):
        for c in range(C):
            if r == 0 or r == R - 1 or c == 0 or c == C - 1:
                heapq.heappush(pq, (heightMap[r][c], r, c))
                visited[r][c] = True
    water = 0
    while pq:
        h, r, c = heapq.heappop(pq)
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and not visited[nr][nc]:
                visited[nr][nc] = True
                if heightMap[nr][nc] < h:
                    water += h - heightMap[nr][nc]
                heapq.heappush(pq, (max(h, heightMap[nr][nc]), nr, nc))
    return water

